<?php
require __DIR__.'/config/bootstrap.php'; requireLogin();
$cart=$_SESSION['carrinho']??[];if(!$cart){setFlash('Sua bolsa está vazia.','warning');redirect('carrinho.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verifyCsrf();$payment=$_POST['forma_pagamento']??'';if(!in_array($payment,['pix','boleto','cartao'],true)){setFlash('Selecione uma forma de pagamento válida.','danger');redirect('finalizar.php');}
 $pdo=db();try{$pdo->beginTransaction();$total=0;$locked=[];
 foreach($cart as $id=>$qty){$s=$pdo->prepare('SELECT id,nome,preco,estoque,ativo FROM produtos WHERE id=:id FOR UPDATE');$s->execute(['id'=>(int)$id]);$p=$s->fetch();$qty=(int)$qty;if(!$p||!$p['ativo']||$qty<1||$qty>(int)$p['estoque'])throw new RuntimeException('Estoque insuficiente ou produto indisponível: '.($p['nome']??'produto'));$p['quantidade']=$qty;$total+=(float)$p['preco']*$qty;$locked[]=$p;}
 $s=$pdo->prepare('INSERT INTO pedidos(usuario_id,forma_pagamento,total) VALUES(:usuario,:pagamento,:total)');$s->execute(['usuario'=>currentUser()['id'],'pagamento'=>$payment,'total'=>$total]);$orderId=(int)$pdo->lastInsertId();$item=$pdo->prepare('INSERT INTO pedido_itens(pedido_id,produto_id,quantidade,preco_unitario) VALUES(:pedido,:produto,:quantidade,:preco)');$stock=$pdo->prepare('UPDATE produtos SET estoque=estoque-:quantidade WHERE id=:id');foreach($locked as $p){$item->execute(['pedido'=>$orderId,'produto'=>$p['id'],'quantidade'=>$p['quantidade'],'preco'=>$p['preco']]);$stock->execute(['quantidade'=>$p['quantidade'],'id'=>$p['id']]);}$pdo->commit();$_SESSION['carrinho']=[];$_SESSION['pedido_confirmado']=$orderId;redirect('pedido_confirmado.php');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();setFlash($e instanceof RuntimeException?$e->getMessage():'Não foi possível concluir o pedido.','danger');redirect('carrinho.php');}
}
$pageTitle='Finalizar compra';require __DIR__.'/includes/header.php'; ?>
